/**
 * generate-link-map.mjs
 * Auto-generated by: scripts/generate-link-map.mjs
 * Do NOT edit src/data/link-map.json manually -- run `npm run build` to regenerate.
 *
 * Scans all article bodies for markdown internal links and writes
 * src/data/link-map.json with per-brand, per-article inbound/outbound maps.
 *
 * Detected link format: [anchor text](/category/slug/) or [anchor text](/category/slug)
 * Only /tableware/, /knives/, and /kitchen/ paths are counted as internal links.
 */

import { readFileSync, readdirSync, writeFileSync } from 'fs';
import { join, resolve } from 'path';
import { fileURLToPath } from 'url';

const rootDir = resolve(fileURLToPath(new URL('.', import.meta.url)), '..');

const CONTENT_DIRS = [
  join(rootDir, 'src', 'content', 'tableware'),
  join(rootDir, 'src', 'content', 'knives'),
  join(rootDir, 'src', 'content', 'kitchen'),
];
const OUTPUT_FILE = join(rootDir, 'src', 'data', 'link-map.json');
const BRANDS_DIR = join(rootDir, 'src', 'data', 'brands');

// Brand detection: loaded dynamically from src/data/brands/*.md.
// The filename (without .md) is the slug keyword; brandEnglish is the canonical display name.
// Which brand keyword appears earliest in the article slug wins.
function loadBrandKeywords() {
  const files = readdirSync(BRANDS_DIR).filter(f => f.endsWith('.md')).sort();
  return files.map(f => {
    const keyword = f.replace('.md', '');
    const content = readFileSync(join(BRANDS_DIR, f), 'utf-8');
    const { frontmatter } = splitContent(content);
    const brandEnglish = yamlScalar(frontmatter, 'brandEnglish');
    return { name: brandEnglish || keyword, keyword };
  });
}

const BRAND_KEYWORDS = loadBrandKeywords();

// Returns { name, keyword } where keyword is the brand profile filename (without .md).
function detectBrand(slug) {
  let earliest = null;
  for (const { name, keyword } of BRAND_KEYWORDS) {
    const idx = slug.indexOf(keyword);
    if (idx !== -1 && (earliest === null || idx < earliest.idx)) {
      earliest = { name, keyword, idx };
    }
  }
  return earliest ? { name: earliest.name, keyword: earliest.keyword } : { name: 'Unknown', keyword: null };
}

// Split raw markdown into frontmatter and body.
function splitContent(raw) {
  const match = raw.match(/^---[\r\n]([\s\S]*?)[\r\n]---[\r\n]?([\s\S]*)$/);
  if (!match) return { frontmatter: '', body: raw };
  return { frontmatter: match[1], body: match[2] };
}

// Extract a top-level YAML scalar by key name.
function yamlScalar(yaml, key) {
  const re = new RegExp(`^${key}:\\s*["']?([^"'\\n]+)["']?`, 'm');
  const m = yaml.match(re);
  return m ? m[1].trim() : null;
}

// Extract outbound internal link slugs from the article body.
// Matches: [anchor text](/category/slug/) and [anchor text](/category/slug)
// Returns a deduplicated array of target slugs.
function extractOutboundSlugs(body) {
  const slugs = new Set();
  const re = /\[([^\]]+)\]\(\/(kitchen|tableware|knives)\/([^/)]+)\/?[^)]*\)/g;
  for (const match of body.matchAll(re)) {
    slugs.add(match[3]);
  }
  return [...slugs];
}

// --- Pass 1: collect all slugs and their outbound links ---

const slugDir = {};      // slug -> absolute dir path
const slugBrand = {};    // slug -> brand name
const outbound = {};     // slug -> slug[]

for (const dir of CONTENT_DIRS) {
  const files = readdirSync(dir).filter(f => f.endsWith('.md')).sort();
  for (const file of files) {
    const slug = file.replace('.md', '');
    slugDir[slug] = dir;
    slugBrand[slug] = detectBrand(slug).name;
    outbound[slug] = [];
  }
}

const allSlugs = Object.keys(slugDir);

for (const slug of allSlugs) {
  const raw = readFileSync(join(slugDir[slug], `${slug}.md`), 'utf-8');
  const { body } = splitContent(raw);
  outbound[slug] = extractOutboundSlugs(body).filter(s => slugDir[s] !== undefined);
}

// --- Pass 2: build inbound map ---

const inbound = {};
for (const slug of allSlugs) inbound[slug] = [];

for (const [fromSlug, toSlugs] of Object.entries(outbound)) {
  for (const toSlug of toSlugs) {
    if (!inbound[toSlug].includes(fromSlug)) {
      inbound[toSlug].push(fromSlug);
    }
  }
}

// --- Group by brand ---

const brandMap = {};
for (const slug of allSlugs) {
  const brand = slugBrand[slug];
  if (!brandMap[brand]) brandMap[brand] = [];
  brandMap[brand].push({
    slug,
    inboundFrom: inbound[slug],
    outboundTo:  outbound[slug],
  });
}

// Sort brands alphabetically, articles within each brand alphabetically.
const brands = {};
for (const brandName of Object.keys(brandMap).sort()) {
  brands[brandName] = brandMap[brandName].sort((a, b) => a.slug.localeCompare(b.slug));
}

// Summary stats for the console message.
const totalLinks = allSlugs.reduce((sum, s) => sum + outbound[s].length, 0);
const articlesWithLinks = allSlugs.filter(s => outbound[s].length > 0).length;

const linkMap = {
  _note: 'Auto-generated by scripts/generate-link-map.mjs -- do not edit manually.',
  generatedAt: new Date().toISOString().slice(0, 10),
  brands,
};

writeFileSync(OUTPUT_FILE, JSON.stringify(linkMap, null, 2) + '\n', 'utf-8');
process.stdout.write(
  `generate-link-map: OK -- ${totalLinks} internal link(s) across ${articlesWithLinks} article(s)\n`,
);
